 for f in["ctl","ack"]{assert!(!r(f).exists());assert!(Command::new("mkfifo").arg(r(f)).status().unwrap().success());}fs::create_dir_all(r("perf")).unwrap();fs::create_dir_all(r("stat")).unwrap();
 let(mut steps,mut jobs)=(vec![],vec![]);let mut add=|pattern:&str,v:&str,block:usize,panel:&str|{let n=format!("{panel}-{block}-{pattern}-{v}");let(bin,mode)=binary(v);let iters=if panel=="preflight"{17}else{100000};let mut a=vec![];let mut data=None;let repeat=if panel=="cycles"{2048}else{1};
  if panel=="cycles"||panel=="stat"{let p=r(if panel=="cycles"{"perf"}else{"stat"}).join(format!("{n}.{}",if panel=="cycles"{"data"}else{"csv"}));a.extend(["sudo".into(),"-n".into(),"env".into(),format!("ZOPRO_BENCH_PERF_CTL={}",r("ctl").display()),format!("ZOPRO_BENCH_PERF_ACK={}",r("ack").display()),format!("ZOPRO_ARITH_PROFILE_REPEATS={repeat}"),"perf".into()]);if panel=="cycles"{a.extend(["record".into(),"--no-buildid-cache".into(),"--sample-cpu".into(),"--timestamp".into(),"-P".into(),"-e".into(),"cycles:u".into(),"-c".into(),"16000000".into(),"-m".into(),"512".into()]);}else{a.extend(["stat".into(),"--no-big-num".into(),"-x".into(),";".into(),"-e".into(),"{cycles:u,instructions:u,cache-misses:u,branch-misses:u}".into()]);}a.extend(["-o".into(),p.display().to_string(),"--delay=-1".into(),format!("--control=fifo:{},{}",r("ctl").display(),r("ack").display()),"--".into()]);data=Some(p);}
  a.extend(["taskset".into(),"-c".into(),"2".into(),bin.clone(),mode,pattern.into(),iters.to_string()]);let mut s=step(&n,a);s["environment"]=json!({"ZOPRO_ARITH_PROFILE_REPEATS":"1"});steps.push(s);jobs.push(json!({"name":n,"pattern":pattern,"variant":v,"block":block,"panel":panel,"iterations":iters,"repeat":repeat,"binary":bin,"data":data}));};
 for p in PS{for v in VS{add(p,v,0,"preflight");}}for b in 0..31{let mut cases=PS;cases.rotate_left(b%6);if b%2==1{cases.reverse();}let mut vs=VS;vs.rotate_left(b%4);if b%2==1{vs.reverse();}for p in cases{for v in vs{add(p,v,b,"latency");}}}for panel in["stat","cycles"]{for p in["square","norm-affine"]{for v in["OFF","SQUARE"]{add(p,v,0,panel);}}}assert_eq!(jobs.len(),776);
